DROP TABLE IF EXISTS d_species_list; CREATE TABLE d_species_list ( code character varying(11)  NULL, family character varying(50)  NULL, genus character varying(50)  NULL, species character varying(50)  NULL, perennial_annual character varying(2)  NULL, woody character varying(2)  NULL, plant_type character varying(2)  NULL, leaves_loss character varying(2)  NULL, author_citation character varying(100)  NULL, cmnt character varying(250)  NULL, reference character varying(250)  NULL, valid_from_survey_year smallint  NULL, valid_to_survey_year smallint  NULL);
